To handle this MongoDB request, you would typically create or update a document in your MongoDB collection that stores marketplace app listings. This document should include fields for the partner name, app details, direct end-user email collection flag, and a custom checkout link.

Here’s an example of how you might structure and insert this document in MongoDB using a Node.js script with the MongoDB driver:

```js
const { MongoClient } = require('mongodb');

async function submitMarketplaceApp() {
  const uri = "your_mongodb_connection_string";
  const client = new MongoClient(uri);

  try {
    await client.connect();
    const database = client.db('marketplaceDB');
    const apps = database.collection('apps');

    const newApp = {
      partner: 'InsightCloud',
      appName: 'InsightCloud MongoDB App',
      description: 'A MongoDB-powered app listed on the marketplace.',
      features: {
        collectsEndUserEmails: true,
        customCheckoutLink: 'https://insightcloud.com/custom-checkout'
      },
      submittedAt: new Date()
    };

    const result = await apps.insertOne(newApp);
    console.log(`App submitted with ID: ${result.insertedId}`);
  } finally {
    await client.close();
  }
}

submitMarketplaceApp().catch(console.error);
```

